import { Context, Effect, Layer } from "effect";
import { Base64 } from "effect/encoding";
import type { Client } from "@atcute/client";
// Side-effecting: registers com.atproto.* lexicons for client.get/post's types.
import "@atcute/atproto";
import { isActorIdentifier, isDid, type Did } from "@atcute/lexicons/syntax";
import { isBlob } from "@atcute/lexicons/interfaces";
import * as v from "@atcute/lexicons/validations";
// Generated by `pnpm run lex:generate` from lexicons/io/placemark/map.json.
import { mainSchema as placemarkMapSchema } from "./lexicons/types/io/placemark/map.js";
import {
  CloudMapDocument,
  CloudMapSummary,
  RecordNotFound,
} from "../../../shared/atproto_rpc";

const COLLECTION = "io.placemark.map";
const BLOB_MIME_TYPE = "application/flatgeobuf";

export interface MapRecordInput {
  name: string;
  symbolization: unknown;
  layer: unknown;
  folders: unknown;
  layerConfigs: unknown;
}

export interface MapRecordOutput extends MapRecordInput {
  dataBytes: Uint8Array;
}

export interface MapRecordSummary {
  name: string;
}

/**
 * The one place a fetched record becomes a CloudMapDocument, shared by the
 * signed-in LoadMap RPC and the public share endpoint so both produce
 * byte-identical documents.
 */
export function mapRecordToDocument(record: MapRecordOutput): CloudMapDocument {
  return new CloudMapDocument({
    dataBase64: Base64.encode(record.dataBytes),
    symbolization: record.symbolization,
    layer: record.layer,
    folders: record.folders,
    layerConfigs: record.layerConfigs,
  });
}

export interface AtprotoRepoShape {
  listMaps(did: string): Effect.Effect<CloudMapSummary[]>;
  getMap(did: string, rkey: string): Effect.Effect<MapRecordOutput, RecordNotFound>;
  // Like getMap but skips fetching the blob bytes, for callers that only need `name`.
  getMapSummary(did: string, rkey: string): Effect.Effect<MapRecordSummary, RecordNotFound>;
  putMap(
    did: string,
    rkey: string,
    record: MapRecordInput,
    blobBytes: Uint8Array,
  ): Effect.Effect<CloudMapSummary>;
  deleteMap(did: string, rkey: string): Effect.Effect<void>;
}

export class AtprotoRepo extends Context.Service<AtprotoRepo, AtprotoRepoShape>()(
  "AtprotoRepo",
) {}

function rkeyFromUri(uri: string): string {
  const parts = uri.split("/");
  return parts[parts.length - 1];
}

// XRPC error responses carry {error: string, message?: string} -- `error`
// alone is just the error code (e.g. "InvalidRequest"), not the reason.
function xrpcErrorMessage(data: { error: string; message?: string }): string {
  return data.message ? `${data.error}: ${data.message}` : data.error;
}

// Narrows a plain string into atcute's branded ActorIdentifier, avoiding an `as` cast.
function asActorIdentifier(did: string) {
  if (!isActorIdentifier(did)) {
    throw new Error(`not a valid DID or handle: ${did}`);
  }
  return did;
}

/**
 * Narrows a plain `did: string` into atcute's branded `Did` type.
 * Used for `com.atproto.sync.getBlob`'s `did` param, which (unlike
 * `com.atproto.repo.*`'s `repo` param) requires a genuine DID rather than
 * the broader `ActorIdentifier` (`Did | Handle`) -- a `Did` already
 * satisfies `ActorIdentifier`, so the result doubles as the `repo` param
 * too. Callers reach this service only after auth_middleware.ts has
 * already validated the DID with `isDid`, so this should never actually
 * throw in practice.
 */
function asDid(did: string): Did {
  if (!isDid(did)) {
    throw new Error(`not a valid DID: ${did}`);
  }
  return did;
}

// `io.placemark.map` IS now a real, registered lexicon (see the import
// above and lexicons/io/placemark/map.json) -- but that registration backs
// the `Records` ambient interface, not `XRPCQueries`/`XRPCProcedures`.
// `com.atproto.repo.getRecord`/`listRecords`/`putRecord` are generic over
// *any* collection at the protocol level, so their own lexicons fix
// `value`/`record` to `unknown` no matter what's registered in `Records`
// (see e.g. node_modules/@atcute/atproto/dist/lexicons/types/com/atproto/repo/getRecord.d.ts:
// `value: v.UnknownSchema`). `@atcute/client` doesn't consult `Records` on
// its own -- nothing in @atcute/client or @atcute/lexicons reads that
// interface. So narrowing `response.data.value` for this collection is
// still our job; the difference from before is that we now do it with the
// *real* per-field validators lex-cli generated from the lexicon
// (`placemarkMapSchema.object.shape`), not hand-rolled `typeof` checks.
//
// `symbolization`/`layer`/`folders`/`layerConfigs` are deliberately left
// unvalidated here even though the lexicon also generates validators for
// them (`v.unknown()`): the app re-validates all four with its own Zod
// schemas, and the generated validator only asserts "is a non-null
// object" (see UNKNOWN_SCHEMA in
// node_modules/@atcute/lexicons/dist/validations/index.js), which adds
// nothing on top of that.
//
// `layer` is the field where that `null` rejection actually bites: the
// app's domain model spells "no base layer" as `null` (see
// state/jotai.ts's default memory meta), which no `unknown` field can
// hold. So `layer` is optional in the lexicon, `putMap` omits the key
// instead of writing null, and `getMap` turns the absent key back into
// `null` for the rest of the codebase.
const placemarkMapShape = placemarkMapSchema.object.shape;

interface StoredMapSummaryValue {
  name: string;
  updatedAt: string;
}

function isStoredMapSummaryValue(value: unknown): value is StoredMapSummaryValue {
  return (
    typeof value === "object" &&
    value !== null &&
    "name" in value &&
    v.is(placemarkMapShape.name, value.name) &&
    "updatedAt" in value &&
    v.is(placemarkMapShape.updatedAt, value.updatedAt)
  );
}

// DAG-CBOR (what atproto records are stored as) has no floating-point
// number type -- only integers, strings, bools, null, bytes, cid, array,
// object. symbolization/layer/folders/layerConfigs commonly contain
// floats (e.g. defaultOpacity), so they're written as JSON-encoded
// strings here, not nested objects, same as fgb_codec.ts's __pm_props.
interface StoredMapRecordValue extends StoredMapSummaryValue {
  data: unknown;
  symbolization: string;
  layer?: string;
  folders: string;
  layerConfigs: string;
}

// `layer` is deliberately absent here, and from the lexicon's `required`
// array: Lexicon has no concept of null, so a map with no base layer is
// written with no `layer` key at all (see `putMap`) rather than
// `layer: null`, which the generated `v.unknown()` validator rejects.
function isStoredMapRecordValue(value: unknown): value is StoredMapRecordValue {
  return (
    isStoredMapSummaryValue(value) &&
    "data" in value &&
    "symbolization" in value &&
    typeof value.symbolization === "string" &&
    "folders" in value &&
    typeof value.folders === "string" &&
    "layerConfigs" in value &&
    typeof value.layerConfigs === "string" &&
    (!("layer" in value) || typeof value.layer === "string")
  );
}

export function AtprotoRepoLive(client: Client): Layer.Layer<AtprotoRepo> {
  return Layer.succeed(
    AtprotoRepo,
    AtprotoRepo.of({
      listMaps: (did) =>
        Effect.promise(async () => {
          const repo = asActorIdentifier(did);
          const response = await client.get("com.atproto.repo.listRecords", {
            params: { repo, collection: COLLECTION },
          });
          if (!response.ok) {
            throw new Error(xrpcErrorMessage(response.data));
          }
          return response.data.records.map((record) => {
            if (!isStoredMapSummaryValue(record.value)) {
              throw new Error(`malformed ${COLLECTION} record at ${record.uri}`);
            }
            return new CloudMapSummary({
              rkey: rkeyFromUri(record.uri),
              name: record.value.name,
              updatedAt: record.value.updatedAt,
            });
          });
        }),

      getMap: (did, rkey) =>
        Effect.tryPromise({
          try: async () => {
            const repoDid = asDid(did);
            const response = await client.get("com.atproto.repo.getRecord", {
              params: { repo: repoDid, collection: COLLECTION, rkey },
            });
            if (!response.ok) {
              throw new Error(xrpcErrorMessage(response.data));
            }
            if (!isStoredMapRecordValue(response.data.value)) {
              throw new Error(`malformed ${COLLECTION} record at ${response.data.uri}`);
            }
            const value = response.data.value;
            if (!isBlob(value.data)) {
              throw new Error(
                `malformed blob reference in ${COLLECTION} record at ${response.data.uri}`,
              );
            }

            // `value.data` is only a *pointer* to the blob (its CID,
            // mimeType, and size) -- the actual FlatGeobuf bytes live on
            // the PDS and have to be fetched separately via
            // `com.atproto.sync.getBlob`. `as: "bytes"` tells atcute's
            // client to read the binary response body with
            // `response.arrayBuffer()` and wrap it in a `Uint8Array`
            // (see @atcute/client's `#perform`), rather than trying to
            // JSON-parse it.
            const blobResponse = await client.get("com.atproto.sync.getBlob", {
              params: { did: repoDid, cid: value.data.ref.$link },
              as: "bytes",
            });
            if (!blobResponse.ok) {
              throw new Error(xrpcErrorMessage(blobResponse.data));
            }

            return {
              name: value.name,
              symbolization: JSON.parse(value.symbolization),
              // The optional, JSON-encoded `layer` key reads back as
              // `null` for "no base layer" (see state/jotai.ts's default
              // memory meta).
              layer: value.layer === undefined ? null : JSON.parse(value.layer),
              folders: JSON.parse(value.folders),
              layerConfigs: JSON.parse(value.layerConfigs),
              dataBytes: blobResponse.data,
            };
          },
          catch: () => new RecordNotFound({ rkey }),
        }),

      getMapSummary: (did, rkey) =>
        Effect.tryPromise({
          try: async () => {
            const repoDid = asDid(did);
            const response = await client.get("com.atproto.repo.getRecord", {
              params: { repo: repoDid, collection: COLLECTION, rkey },
            });
            if (!response.ok) {
              throw new Error(xrpcErrorMessage(response.data));
            }
            if (!isStoredMapSummaryValue(response.data.value)) {
              throw new Error(`malformed ${COLLECTION} record at ${response.data.uri}`);
            }
            return { name: response.data.value.name };
          },
          catch: () => new RecordNotFound({ rkey }),
        }),

      putMap: (did, rkey, record, blobBytes) =>
        Effect.promise(async () => {
          const repo = asActorIdentifier(did);

          // `uploadBlob`'s input is typed as `Blob | ArrayBuffer |
          // ArrayBufferView | ReadableStream` (it's an XRPCBlobBodyParam,
          // not a lex-schema body). atcute's client deliberately does NOT
          // set a `content-type` header itself for this kind of binary
          // input (see node_modules/@atcute/client/dist/client.js: the
          // `_mergeHeaders` default for 'content-type' is `null`, which is
          // skipped, whenever `input` is a Blob/ArrayBuffer/view/stream).
          // Content type is instead inferred the standard Fetch-API way:
          // from the `Blob`'s own `.type`, which the underlying `fetch`
          // turns into the request's `content-type` header automatically.
          // So we must pass an actual `Blob` with `type` set, not a bare
          // `Uint8Array`, or the upload would go out with no content type.
          const uploadResponse = await client.post("com.atproto.repo.uploadBlob", {
            input: new Blob([blobBytes], { type: BLOB_MIME_TYPE }),
          });
          if (!uploadResponse.ok) {
            throw new Error(xrpcErrorMessage(uploadResponse.data));
          }

          const updatedAt = new Date().toISOString();
          const putResponse = await client.post("com.atproto.repo.putRecord", {
            input: {
              repo,
              collection: COLLECTION,
              rkey,
              record: {
                $type: COLLECTION,
                name: record.name,
                updatedAt,
                data: uploadResponse.data.blob,
                symbolization: JSON.stringify(record.symbolization),
                // Lexicon fields are "present with a value, or entirely
                // absent" -- there is no null. A map with no base layer
                // (the app's default) therefore writes no `layer` key,
                // rather than a `layer: null` that the lexicon's own
                // `unknown` validator would reject.
                ...(record.layer === null || record.layer === undefined
                  ? {}
                  : { layer: JSON.stringify(record.layer) }),
                folders: JSON.stringify(record.folders),
                layerConfigs: JSON.stringify(record.layerConfigs),
              },
            },
          });
          if (!putResponse.ok) {
            throw new Error(xrpcErrorMessage(putResponse.data));
          }

          return new CloudMapSummary({ rkey, name: record.name, updatedAt });
        }),

      deleteMap: (did, rkey) =>
        Effect.promise(async () => {
          const repo = asActorIdentifier(did);
          const response = await client.post("com.atproto.repo.deleteRecord", {
            input: { repo, collection: COLLECTION, rkey },
          });
          if (!response.ok) {
            throw new Error(xrpcErrorMessage(response.data));
          }
        }),
    }),
  );
}
